import{_ as t,a as n,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","description":"学习 名词化与施事信息，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","description":"学习 名词化与施事信息，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 名词化与施事信息，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 24 Beauty","link":"/life/english/new-concept/book-4/unit-03/lesson-024"},"next":{"text":"第四册：流利英语 · Lesson 26 The past life of the earth","link":"/life/english/new-concept/book-4/unit-04/lesson-026"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 24 Beauty","link":"/life/english/new-concept/book-4/unit-03/lesson-024"},"next":{"text":"第四册：流利英语 · Lesson 26 The past life of the earth","link":"/life/english/new-concept/book-4/unit-04/lesson-026"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-025.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-025.md"}'),i={name:"life/english/new-concept/book-4/unit-04/lesson-025.md"};function r(s,e,l,c,d,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-25-non-auditory-effects-of-noise" tabindex="-1">第四册：流利英语 · Lesson 25 Non-auditory effects of noise <a class="header-anchor" href="#第四册-流利英语-·-lesson-25-non-auditory-effects-of-noise" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 25 Non-auditory effects of noise&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕噪声影响阅读研究型文字，注意标题强调的不只是听觉体验。课堂练习把噪声、注意力和任务表现当作可检验变量，区分主观不适与测量结果，避免由旧文章直接推出当代医学结论。重点用名词化压缩过程，同时防止把关联包装成已经确认的因果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>noise</td><td>/nɔɪz/</td><td>n.</td><td>噪声</td><td>background noise</td></tr><tr><td>concentration</td><td>/ˌkɒnsənˈtreɪʃən/</td><td>n.</td><td>注意力</td><td>sustained concentration</td></tr><tr><td>interruption</td><td>/ˌɪntəˈrʌpʃən/</td><td>n.</td><td>打断</td><td>frequent interruptions</td></tr><tr><td>performance</td><td>/pəˈfɔːməns/</td><td>n.</td><td>表现</td><td>task performance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be exposed to — 接触某环境因素</li><li>interfere with — 干扰某过程</li></ul><h2 id="语法讲解-名词化与施事信息" tabindex="-1">语法讲解：名词化与施事信息 <a class="header-anchor" href="#语法讲解-名词化与施事信息" aria-label="Permalink to &quot;语法讲解：名词化与施事信息&quot;">​</a></h2><p>名词化把动词或形容词转为名词表达，例如 people concentrate → concentration。它便于讨论抽象过程，但可能隐藏谁做了什么：a reduction in errors 没有说明谁减少了错误，也不说明原因。介词选择应随搭配，如 exposure to noise、an increase in interruptions。改写时保留时间、对象与证据强度，不能把 may affect 改成 the effect of 就暗中确认影响已存在。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A reduction in background noise coincided with fewer interruptions during the task.</p></blockquote><p>背景噪声的减少与任务过程中打断次数的下降同时出现。</p><p>A reduction… 是名词化主语；coincided with 只说明同时发生，没有直接宣称因果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>exposure of noise 应改 exposure to noise；coincided with 也不能自动替换为 caused。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先读 reduction、concentration、interruption，标出重音；再读示例，确保长名词不会被重读成每个音节等重。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A reduction in corridor noise coincided with fewer interruptions. Staff completed the sorting task more quickly. A change in the task instructions may also have contributed.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构办公观察，记录噪声变化、任务表现和一个替代解释。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>名词化方便总结，但最后一句保留其他解释，避免过度推断。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：exposure ___ background noise。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> exposure to 为常见搭配。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把 The number of interruptions increased. 改为名词短语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> an increase in the number of interruptions</p><p><strong>解析：</strong> increase 名词后用 in 说明增加的项目。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例中的 coincided with 是否等于 caused？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不等于。</p><p><strong>解析：</strong> 同时出现不自动证明因果。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：名词化与施事信息。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-026">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(i,[["render",r]]);export{p as __pageData,f as default};
